export class Counter {
  readonly name: string;
  #count = 0;
  #history: number[] = [];

  constructor(name: string) {
    this.name = name;
  }

  increment(by = 1): void {
    this.#count += by;
    this.#history.push(this.#count);
  }

  value(): number {
    return this.#count;
  }

  history(): readonly number[] {
    return this.#history;
  }
}

const visits = new Counter("visits");
visits.increment();
visits.increment(5);
visits.increment();
console.log(`${visits.name}: ${visits.value()}`);
console.log(`History: ${visits.history().join(", ")}`);
console.log(`Keys: ${Object.keys(visits).join(", ")}`);

