steps.body:
A getter is a method that reads like a field. Give it a return type, and callers use it without parentheses:

```typescript
class Rectangle {
  width: number;
  height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  get area(): number {
    return this.width * this.height;
  }
}

console.log(new Rectangle(3, 4).area); // 12
```

A setter runs when you assign to the property, so it can check the value before storing it, and every assignment is checked against its parameter type. A getter with no setter is read-only, and assigning to it is TS2540.

A `static` member belongs to the class itself, not to each instance, and you reach it through the class name. A static factory is a static method that returns a new instance, like `Temperature.fromJSON(json)`. It suits input from outside the program, such as parsed JSON: take it as `unknown`, narrow it, and only then call the constructor, so every instance starts out valid.

examples.code:
type CartLine = { name: string; priceCents: number; qty: number };

class Cart {
  lines: CartLine[] = [];

  add(line: CartLine): void {
    this.lines.push(line);
  }

  get count(): number {
    return this.lines.reduce((sum, line) => sum + line.qty, 0);
  }

  get total(): number {
    return this.lines.reduce((sum, line) => sum + line.priceCents * line.qty, 0);
  }
}

const cart = new Cart();
cart.add({ name: "Mug", priceCents: 1299, qty: 2 });
console.log(`${cart.count} items: $${(cart.total / 100).toFixed(2)}`);

cart.add({ name: "Tea", priceCents: 450, qty: 3 });
const total = cart.total;
//    ^? const total: number
console.log(`${cart.count} items: $${(total / 100).toFixed(2)}`);

class Thermostat {
  static readonly ABSOLUTE_ZERO = -273.15;
  #celsius = 20;

  get celsius(): number {
    return this.#celsius;
  }

  set celsius(value: number) {
    if (value < Thermostat.ABSOLUTE_ZERO) {
      throw new RangeError(`${value}°C is below absolute zero`);
    }
    this.#celsius = value;
  }
}

const thermostat = new Thermostat();
thermostat.celsius = 22.5;
console.log(`Set to ${thermostat.celsius}°C`);

try {
  thermostat.celsius = -300;
} catch (err) {
  console.log(err instanceof Error ? err.message : String(err));
}
console.log(`Still ${thermostat.celsius}°C`);

class Temperature {
  readonly celsius: number;

  constructor(celsius: number) {
    this.celsius = celsius;
  }

  static fromJSON(json: unknown): Temperature {
    if (
      typeof json === "object" &&
      json !== null &&
      "celsius" in json &&
      typeof json.celsius === "number"
    ) {
      return new Temperature(json.celsius);
    }
    throw new Error(`Not a temperature: ${JSON.stringify(json)}`);
  }
}

const inputs = ['{"celsius": 21.5}', '{"celsius": "warm"}', "[]"];
for (const text of inputs) {
  try {
    const temperature = Temperature.fromJSON(JSON.parse(text));
    console.log(`Read ${temperature.celsius}°C`);
  } catch (err) {
    console.log(err instanceof Error ? err.message : String(err));
  }
}

