export class Temperature {
  #celsius: number;

  constructor(celsius: number) {
    this.#celsius = celsius;
  }

  get celsius(): number {
    return this.#celsius;
  }

  get fahrenheit(): number {
    return this.#celsius * 9 / 5 + 32;
  }

  set fahrenheit(f: number) {
    this.#celsius = (f - 32) * 5 / 9;
  }

  static fromFahrenheit(f: number): Temperature {
    return new Temperature((f - 32) * 5 / 9);
  }
}

const boiling = new Temperature(100);
console.log(`${boiling.celsius.toFixed(1)}°C = ${boiling.fahrenheit.toFixed(1)}°F`);

const body = Temperature.fromFahrenheit(98.6);
console.log(`${body.fahrenheit.toFixed(1)}°F = ${body.celsius.toFixed(1)}°C`);

const room = new Temperature(20);
room.fahrenheit = 77;
console.log(`Room: ${room.celsius.toFixed(1)}°C`);

tests.append:
const freezing = Temperature.fromFahrenheit(32);
console.log(`${freezing.celsius.toFixed(1)} ${freezing.fahrenheit.toFixed(1)}`);
const cold = new Temperature(-40);
console.log(cold.fahrenheit.toFixed(1));
cold.fahrenheit = 212;
console.log(cold.celsius.toFixed(1));

steps.body:
`class Circle extends Shape` works as it does in JavaScript: the subclass gets every member of its base class, and its constructor calls `super(...)` before it touches `this`. TypeScript adds one keyword. A method that replaces a base class method is marked `override`:

```typescript
class Animal {
  speak(): string {
    return "...";
  }
}

class Dog extends Animal {
  override speak(): string {
    return "Woof";
  }
}

console.log(new Dog().speak()); // Woof
```

The course config turns on `noImplicitOverride`, so replacing a method without `override` is TS4114, and `override` on a method the base doesn't have is TS4113. Together they catch a renamed base method: the subclass's method stops compiling, instead of quietly turning into a separate method that nothing calls.

An override must fit the base method's type. That's what lets a subclass instance stand in for its base: a `Circle` is a `Shape`, so a `Shape[]` can hold circles and rectangles, and calling `area()` on each item runs that object's own version.

examples.code:
class Shape {
  name: string;

  constructor(name: string) {
    this.name = name;
  }

  area(): number {
    return 0;
  }
}

class Circle extends Shape {
  radius: number;

  constructor(radius: number) {
    super("circle");
    this.radius = radius;
  }

  override area(): number {
    return Math.PI * this.radius ** 2;
  }
}

class Rect extends Shape {
  width: number;
  height: number;

  constructor(width: number, height: number) {
    super("rect");
    this.width = width;
    this.height = height;
  }

  override area(): number {
    return this.width * this.height;
  }
}

const circle = new Circle(2);
const rect = new Rect(3, 4);
console.log(`${circle.name}: ${circle.area().toFixed(2)}`);
console.log(`${rect.name}: ${rect.area()}`);

class Shape {
  area(): number {
    return 0;
  }
}

class Square extends Shape {
  side: number;

  constructor(side: number) {
    super();
    this.side = side;
  }

  area(): number {
    return this.side ** 2;
  }
}

console.log(new Square(3).area());

examples.explanation:
`Square` replaces `area()` but doesn't say so, and `noImplicitOverride` turns that into TS4114. Writing `override area(): number` fixes it. The rule pays off later, when the base class changes. Say someone renames `area()` to `surface()`, and the subclass still says `override area()`:

```typescript error
class Shape {
  surface(): number {
    return 0;
  }
}

class Square extends Shape {
  side: number;

  constructor(side: number) {
    super();
    this.side = side;
  }

  override area(): number {
    return this.side ** 2;
  }
}

console.log(new Square(3).surface());
```

Now it's TS4113: `This member cannot have an 'override' modifier because it is not declared in the base class 'Shape'.` Without the keyword, `area()` would quietly become a new method, and every call to `surface()` on a square would return 0.

examples.code:
class Shape {
  name: string;

  constructor(name: string) {
    this.name = name;
  }

  area(): number {
    return 0;
  }

  describe(): string {
    return `${this.name} with area ${this.area().toFixed(2)}`;
  }
}

class Circle extends Shape {
  radius: number;

  constructor(radius: number) {
    super("circle");
    this.radius = radius;
  }

  override area(): number {
    return Math.PI * this.radius ** 2;
  }

  override describe(): string {
    return `${super.describe()} (radius ${this.radius})`;
  }
}

class Rect extends Shape {
  width: number;
  height: number;

  constructor(width: number, height: number) {
    super("rect");
    this.width = width;
    this.height = height;
  }

  override area(): number {
    return this.width * this.height;
  }
}

const shapes: Shape[] = [new Circle(1), new Rect(2, 3), new Circle(0.5)];
for (const shape of shapes) {
  console.log(shape.describe());
}
const total = shapes.reduce((sum, shape) => sum + shape.area(), 0);
console.log(`Total area: ${total.toFixed(2)}`);

examples.explanation:
`shapes` is a `Shape[]`, and circles and rectangles fit because a subclass has everything its base class has. The loop only knows that each item is a `Shape`, yet `describe()` runs each object's own version. That's polymorphism. `Circle` overrides `describe()` and calls `super.describe()` to reuse the base text before adding the radius, while `Rect` keeps the base version. The base `describe()` calls `this.area()`, which runs the override, so every line shows its shape's real area.

Through the `Shape` type you can only use `Shape`'s members:

```typescript error
class Shape {
  area(): number {
    return 0;
  }
}

class Circle extends Shape {
  radius = 1;

  override area(): number {
    return Math.PI * this.radius ** 2;
  }
}

const shapes: Shape[] = [new Circle()];
for (const shape of shapes) {
  console.log(shape.radius);
}
```

That's TS2339, since a `Shape` has no `radius`. Narrow it first with `if (shape instanceof Circle)`.

