export class Employee {
  name: string;
  salary: number;

  constructor(name: string, salary: number) {
    this.name = name;
    this.salary = salary;
  }

  describe(): string {
    return `${this.name} earns $${this.salary}`;
  }
}

export class Manager extends Employee {
  reports: string[];

  constructor(name: string, salary: number, reports: string[]) {
    super(name, salary);
    this.reports = reports;
  }

  override describe(): string {
    const names = this.reports.length > 0 ? this.reports.join(", ") : "no one";
    return `${super.describe()} and manages ${names}`;
  }
}

const people: Employee[] = [
  new Employee("Ben", 85000),
  new Manager("Ana", 120000, ["Ben", "Caro"]),
  new Manager("Dev", 95000, []),
];

for (const person of people) {
  console.log(person.describe());
}

